function ledgerTreeCheck(tree) {
    function build(values) {
        if (values.length === 0)
            return null;
        const root = { value: values[0], left: null, right: null };
        const queue = [root];
        let index = 1;
        while (queue.length > 0 && index < values.length) {
            const node = queue.shift();
            const left = values[index++];
            if (left !== undefined && left !== null)
                queue.push(node.left = { value: left, left: null, right: null });
            const right = values[index++];
            if (right !== undefined && right !== null)
                queue.push(node.right = { value: right, left: null, right: null });
        }
        return root;
    }
    function allSatisfy(node, test) {
        if (node === null)
            return true;
        return test(node.value) && allSatisfy(node.left, test) && allSatisfy(node.right, test);
    }
    function valid(node) {
        if (node === null)
            return true;
        if (!allSatisfy(node.left, (amount) => amount < node.value))
            return false;
        if (!allSatisfy(node.right, (amount) => amount > node.value))
            return false;
        return valid(node.left) && valid(node.right);
    }
    return valid(build(tree));
}

function ledgerTreeCheck(tree) {
    function build(values) {
        if (values.length === 0)
            return null;
        const root = { value: values[0], left: null, right: null };
        const queue = [root];
        let index = 1;
        while (queue.length > 0 && index < values.length) {
