            const right = values[index++];
            if (right !== undefined && right !== null)
                queue.push(node.right = { value: right, left: null, right: null });
        }
        return root;
    }
    function within(node, low, high) {
        if (node === null)
            return true;
        if (node.value <= low || node.value >= high)
            return false;
        return within(node.left, low, node.value) && within(node.right, node.value, high);
    }
    return within(build(tree), -Infinity, Infinity);
